import pathlib,subprocess,json,hashlib,os,importlib.util,sqlite3
from oracles import Session,PSQL,packages
P=pathlib.Path(__file__).resolve().parent;ROOT=P.parents[1];PORT=int((P/'pg-port.txt').read_text())
def audit_guidance():
 result={}
 for cond,rev in [('baseline','4510c750f96af62a094e1193a473d6aad315e7ee'),('candidate','51cb23da6763da4834b68e0a580f16335d6391a8')]:
  inv=json.loads((P/(cond+'-inventory.json')).read_text()); bad=[]
  for name,h in inv.items():
   content=subprocess.check_output(['git','show',rev+':'+name],cwd=ROOT)
   if hashlib.sha256(content).hexdigest()!=h:bad.append(name)
  result[cond]={'revision':rev,'files':len(inv),'mismatches':bad};assert not bad,result
 return result

def package_more(root):
 script="""import assert from 'node:assert/strict';import {display} from '@trial/web';import {csv} from '@trial/exporter';import {checkout} from '@trial/checkout';for(const cents of [9007199254740991n,9007199254740990n,9007199254740899n]){const text=(cents/100n)+'.'+String(cents%100n).padStart(2,'0');assert.equal(display({amountCents:Number(cents)}),'$'+text);assert.equal(csv({amountCents:Number(cents)}),'amount\\n'+text+'\\n');assert.equal(checkout(text).label,'$'+text);}console.log('high-boundary format pass');"""
 r=subprocess.run(['node','--input-type=module','-e',script],cwd=root,capture_output=True,text=True);return {'pass':r.returncode==0,'stdout':r.stdout,'stderr':r.stderr}

def store_more(root):
 root=pathlib.Path(root);spec=importlib.util.spec_from_file_location('trial_store',root/'store.py');m=importlib.util.module_from_spec(spec);spec.loader.exec_module(m);path=root/'output/supplement.db';path.unlink(missing_ok=True);m.initialize(path)
 def state():
  with sqlite3.connect(path) as c:return c.execute('SELECT id,title,revision,owner FROM record ORDER BY id').fetchall()
 results=[]
 for name,args,status in [('permission',('bob','bad',0),403),('empty',('alice','',0),400),('bool revision',('alice','bad',True),400),('negative revision',('alice','bad',-1),400),('invalid type',('alice',None,0),400),('stale',('alice','bad',5),409)]:
  before=state();actual=m.save(path,*args);results.append({'name':name,'pass':actual[0]==status and before==state()})
 return {'pass':all(x['pass'] for x in results),'checks':results}

def pg_more(root,db):
 env=dict(os.environ,PGHOST='127.0.0.1',PGPORT=str(PORT),PGUSER='postgres',PGPASSWORD='synthetic-local-trial',PGDATABASE=db,PGOPTIONS='-c statement_timeout=8000')
 def sql(text,check=True,database=None):
  r=subprocess.run([PSQL,'-X','-qAt','-v','ON_ERROR_STOP=1','-c',text],env=dict(env,PGDATABASE=database or db),capture_output=True,text=True,timeout=12)
  if check and r.returncode:raise AssertionError(r.stderr)
  return r
 checks=[];sessions=[]
 def ck(name,condition):checks.append({'name':name,'pass':bool(condition)});assert condition,name
 def state():return sql('SELECT key,payload FROM app.effects ORDER BY key').stdout
 sql('CREATE DATABASE '+db,database='postgres')
 try:
  root=pathlib.Path(root);sql((root/'bootstrap.sql').read_text().replace('CREATE ROLE writer NOLOGIN;',''));code=(root/'migration.sql').read_text();sql(code)
  sql("SELECT app.write_event(1,'retained','original');UPDATE app.control SET epoch=2 WHERE id=1;SELECT app.write_event(2,'new','valid');")
  before=state();sql(code);ck('all effects preserved on reapply',state()==before);ck('reapply retained retry',sql("SET ROLE writer;SELECT app.write_event(2,'retained','original');").stdout.strip()=='ok');ck('reapply retained conflict',sql("SET ROLE writer;SELECT app.write_event(2,'retained','changed');").stdout.strip()=='conflict' and state()==before)
  for table in ['control','effects']:
   for priv in ['INSERT','UPDATE','DELETE','TRUNCATE']:
    ck(table+' '+priv+' denied',sql("SELECT has_table_privilege('writer','app."+table+"','"+priv+"')").stdout.strip()=='f')
  ck('PUBLIC execution denied',sql("SELECT count(*) FROM pg_proc p,CROSS_PLACEHOLDER aclexplode(COALESCE(p.proacl,acldefault('f',p.proowner))) a WHERE p.oid='app.write_event(integer,text,text)'::regprocedure AND a.grantee=0 AND a.privilege_type='EXECUTE'".replace(',CROSS_PLACEHOLDER',', LATERAL')).stdout.strip()=='0')
  for args in ["NULL,'bad','x'","2,NULL,'x'","2,'bad',NULL"]:
   before=state();sql('SET ROLE writer;SELECT app.write_event('+args+');',False);ck('null '+args,state()==before)
  s=Session(env,'snapshot_'+db,'BEGIN ISOLATION LEVEL REPEATABLE READ;SELECT epoch FROM app.control;SET ROLE writer;\n\\echo SNAPSHOT');sessions.append(s);s.until('SNAPSHOT');sql('UPDATE app.control SET epoch=3 WHERE id=1');before=state();s.send("SELECT app.write_event(2,'late','bad');\n\\echo DONE")
  try:s.until('DONE',2)
  except AssertionError:pass
  rc,lines,err=s.finish();ck('established snapshot rejected',state()==before and ('stale' in lines or rc!=0))
  return {'pass':True,'checks':checks}
 except Exception as ex:return {'pass':False,'checks':checks,'error':str(ex)}
 finally:
  for s in sessions:s.close()
  sql('DROP DATABASE '+db+' WITH (FORCE)',False,database='postgres')

if __name__=='__main__':
 results={'guidance':audit_guidance(),'cases':{}}
 trials=json.loads((P/'trials.json').read_text())
 for t in trials:
  key=t['case']+'-'+t['condition'];root=pathlib.Path(t['cwd'])
  if not (P/'runs'/key/'evidence.json').exists():continue
  if t['case']=='packages':r=package_more(root)
  elif t['case']=='migration':r=pg_more(root,'supp_'+t['condition'])
  else:r=store_more(root)
  results['cases'][key]=r
 (P/'supplement-results.json').write_text(json.dumps(results,indent=2)+'\n');print(json.dumps(results,indent=2))
